1	use super::*;
2	
3	pub struct Param {
4	    pub name: String,
5	    pub ty: metadata::Type,
6	    pub attributes: metadata::ParamAttributes,
7	    pub attrs: Vec<syn::Attribute>,
8	}
9	
10	impl Encoder<'_> {
11	    fn parse_param_attributes(
12	        &mut self,
13	        attrs: &[syn::Attribute],
14	        ty: &metadata::Type,
15	    ) -> Result<metadata::ParamAttributes, Error> {
16	        let mut attributes = metadata::ParamAttributes::default();
17	
18	        for attr in attrs {
19	            if attr.path().is_ident("out") {
20	                if !matches!(attr.meta, syn::Meta::Path(_)) {
21	                    return self.err(attr, "`out` attribute does not accept arguments");
22	                }
23	                attributes |= metadata::ParamAttributes::Out;
24	            } else if attr.path().is_ident("r#in") {
25	                if !matches!(attr.meta, syn::Meta::Path(_)) {
26	                    return self.err(attr, "`in` attribute does not accept arguments");
27	                }
28	                attributes |= metadata::ParamAttributes::In;
29	            } else if attr.path().is_ident("opt") {
30	                if !matches!(attr.meta, syn::Meta::Path(_)) {
31	                    return self.err(attr, "`opt` attribute does not accept arguments");
32	                }
33	                attributes |= metadata::ParamAttributes::Optional;
34	            }
35	        }
36	
37	        if !attributes.contains(metadata::ParamAttributes::Out)
38	            && !attributes.contains(metadata::ParamAttributes::In)
39	        {
40	            if matches!(ty, metadata::Type::RefMut(_) | metadata::Type::PtrMut(..)) {
41	                attributes |= metadata::ParamAttributes::Out;
42	            } else {
43	                attributes |= metadata::ParamAttributes::In;
44	            }
45	        }
46	
47	        Ok(attributes)
48	    }
49	
50	    pub fn param(&mut self, param: &syn::PatType) -> Result<Param, Error> {
51	        let syn::Pat::Ident(ref name) = *param.pat else {
52	            return self.err(param, "param name not found");
53	        };
54	
55	        let name = name.ident.to_string();
56	        let ty = self.encode_type(&param.ty)?;
57	        let attributes = self.parse_param_attributes(&param.attrs, &ty)?;
58	
59	        Ok(Param {
60	            name,
61	            ty,
62	            attributes,
63	            attrs: param.attrs.clone(),
64	        })
65	    }
66	
67	    pub fn bare_param(&mut self, param: &syn::BareFnArg) -> Result<Param, Error> {
68	        let Some((ref name, _)) = param.name else {
69	            return self.err(param, "param name not found");
70	        };
71	
72	        let ty = self.encode_type(&param.ty)?;
73	        let attributes = self.parse_param_attributes(&param.attrs, &ty)?;
74	
75	        Ok(Param {
76	            name: name.unraw_to_string(),
77	            ty,
78	            attributes,
79	            attrs: param.attrs.clone(),
80	        })
81	    }
82	
83	    pub fn encode_return_attrs(&mut self, return_attrs: &[syn::Attribute]) -> Result<(), Error> {
84	        if !return_attrs.is_empty() {
85	            let param_id = self
86	                .output
87	                .Param("", 0, metadata::ParamAttributes::default());
88	            self.encode_attrs(
89	                metadata::writer::HasAttribute::Param(param_id),
90	                return_attrs,
91	                &[],
92	            )?;
93	        }
94	        Ok(())
95	    }
96	
97	    pub fn encode_params(&mut self, params: &[Param]) -> Result<(), Error> {
98	        for (sequence, param) in params.iter().enumerate() {
99	            let param_id = self.output.Param(
100	                &param.name,
101	                (sequence + 1).try_into().unwrap(),
102	                param.attributes,
103	            );
104	            self.encode_attrs(
105	                metadata::writer::HasAttribute::Param(param_id),
106	                &param.attrs,
107	                &["r#in", "out", "opt"],
108	            )?;
109	        }
110	        Ok(())
111	    }
112	
113	    pub fn collect_params(&mut self, sig: &syn::Signature) -> Result<Vec<Param>, Error> {
114	        let mut params = vec![];
115	        let mut param_names = HashSet::new();
116	
117	        for arg in &sig.inputs {
118	            match arg {
119	                syn::FnArg::Receiver(receiver) => {
120	                    return self.err(receiver, "unexpected `self` parameter");
121	                }
122	                syn::FnArg::Typed(pt) => {
123	                    let syn::Pat::Ident(ref name) = *pt.pat else {
124	                        return self.err(pt, "param name not found");
125	                    };
126	
127	                    if !param_names.insert(name.ident.to_string()) {
128	                        return self.err(&name.ident, "param names must be unique");
129	                    }
130	
131	                    params.push(self.param(pt)?);
132	                }
133	            }
134	        }
135	
136	        Ok(params)
137	    }
138	}
