/// A property shorthand declaration inside an interface body.
///
/// Parsed from the syntax `[#[get] | #[set]] Name: Type;`.  Without any attribute both a
/// getter and a setter are generated; with `#[get]` only a getter is generated; with
/// `#[set]` only a setter is generated.
#[derive(Debug)]
pub struct Property {
    pub attrs: Vec<syn::Attribute>,
    pub name: syn::Ident,
    pub ty: syn::Type,
}

/// An event shorthand declaration inside a WinRT interface body.
///
/// Parsed from the syntax `event Name: HandlerType;`.  Generates `add_Name` and
/// `remove_Name` method pairs with the `SpecialName` flag.
#[derive(Debug)]
pub struct Event {
    pub name: syn::Ident,
    pub handler_ty: syn::Type,
}

/// Discriminated union of all member kinds that can appear inside an interface body.
#[derive(Debug)]
pub enum InterfaceMember {
    Method(Method),
    Property(Property),
    Event(Event),
}

impl syn::parse::Parse for InterfaceMember {
    fn parse(input: syn::parse::ParseStream) -> syn::Result<Self> {
        let attrs = input.call(syn::Attribute::parse_outer)?;

        // `event Name: HandlerType;`
        if input.peek(event) && input.peek2(syn::Ident) {
            input.parse::<event>()?;
            let name = input.parse()?;
            input.parse::<syn::Token![:]>()?;
            let handler_ty = input.parse()?;
            input.parse::<syn::Token![;]>()?;
            return Ok(InterfaceMember::Event(Event { name, handler_ty }));
        }

        // `fn name(...) -> ...;`
        if input.peek(syn::Token![fn]) {
            return Ok(InterfaceMember::Method(Method::parse_with_attrs(
                attrs, input,
            )?));
        }

        // `Name: Type;` property shorthand.
        for attr in &attrs {
            let is_get = attr.path().is_ident("get");
            let is_set = attr.path().is_ident("set");
            if !is_get && !is_set {
                return Err(syn::Error::new_spanned(
                    attr,
                    "only `#[get]` and `#[set]` attributes are supported on properties",
                ));
            }
        }

        let has_get = attrs.iter().any(|attr| attr.path().is_ident("get"));
        let has_set = attrs.iter().any(|attr| attr.path().is_ident("set"));
        if has_get && has_set {
            return Err(syn::Error::new_spanned(
                &attrs[1],
                "property cannot have both `#[get]` and `#[set]` attributes",
            ));
        }

        let name = input.parse()?;
        input.parse::<syn::Token![:]>()?;
        let ty = input.parse()?;
        input.parse::<syn::Token![;]>()?;
        Ok(InterfaceMember::Property(Property { attrs, name, ty }))
    }
}

