+#[test]
+fn use_glob_resolves_type() {
+    let output = std::env::temp_dir().join("windows_rdl_use_glob_resolves_type.winmd");
+
+    reader()
+        .input_str(
+            r#"
+use Other::*;
+
+#[winrt]
+mod Test {
+    struct Thing {
+        a: Point,
+    }
+}
+
+#[winrt]
+mod Other {
+    struct Point {
+        x: i32,
+        y: i32,
+    }
+}
+        "#,
+        )
+        .output(&output.to_string_lossy())
+        .write()
+        .unwrap();
+}
